(* [comment removed for export] *)
Definition sc_W4 (lo spa S regb : Z) : list (Z * Z) :=
  [(lo, spa + 80); (S, S + 272); (regb + 8, regb + 48); (AERRNO, AERRNO + 4)]%Z.

(* [comment removed for export] *)
Definition appw (iv : Z * Z) : Prop := snd iv <= ALOWSH_LO \/ AHI_LO <= fst iv.

Lemma appw_off_shadow : forall W a k, Forall appw W -> ALOWSH_LO <= a -> a + k <= AHI_LO -> disjoint_from W a k.
Proof.
  intros W a k FW Ha Hk. apply disjoint_from_Forall. eapply Forall_impl; [| exact FW]. intros [l h] [K|K]; cbn [fst snd] in *; lia.
Qed.

