  (* [comment removed for export] *)
  Definition fr3_XS (ff fp : Z) : list (Z * Z) := [(as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 512); (sh ff, sh ff + 64)]%Z.

  Lemma fr3_XS_scratch : forall LF ff fp, fresh_frame H LF 3 ff fp -> Forall (fs_scratch H LF) (fr3_XS ff fp).
  Proof.
    intros LF ff fp FF. pose proof (fs_scratch_of_fresh H _ _ _ _ FF) as FX. unfold fr3_XS.
    replace (fsz 3) with 512 in FX by reflexivity. replace (fshn 3) with 64 in FX by reflexivity.
    pose proof (Forall_inv FX) as A1. pose proof (Forall_inv (Forall_inv_tail FX)) as A2.
    pose proof (Forall_inv (Forall_inv_tail (Forall_inv_tail FX))) as A3. pose proof (Forall_inv (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail FX)))) as A4.
    repeat apply Forall_cons; [exact A1| exact A2| exact A3| exact A4| apply Forall_nil].
  Qed.

  Lemma sc_W4_appw : forall lo spa S regb, aceil <= lo -> aapp S NEWSZ_SCH -> aapp regb NEWSZ_REG -> Forall appw (sc_W4 lo spa S regb).
  Proof.
    intros lo spa S regb CEIL APS APR. pose proof aceil_facts as (AF & _).
    pose proof (aapp_not_shadowland _ _ APS) as NS. pose proof (aapp_not_shadowland _ _ APR) as NR.
    unfold sc_W4, appw, NEWSZ_SCH, NEWSZ_REG, AHI_LO, ALOWSH_LO in *. rewrite AERRNO_val.
    repeat apply Forall_cons; cbn [fst snd]; [right; lia| lia| lia| left; lia| apply Forall_nil].
  Qed.
